widget.prelude:
def check_ring(n, answer):
    # the checker: any valid string passes
    if n == 1:
        return answer == -1
    if not isinstance(answer, str) or len(answer) != n or not set(answer) <= set("abc"):
        return False
    return all(answer[i] != answer[(i + 1) % n] for i in range(n))

widget.solution:
def ring_string(n):
    if n == 1:
        return -1
    if n % 2 == 0:
        return "ab" * (n // 2)
    return "ab" * (n // 2) + "c"
